mapper.update:
UPDATE runrun_v2.mock_channel_results
SET result = #{result,jdbcType=VARCHAR},
    version = version + 1
WHERE resource_type = #{resourceType,jdbcType=VARCHAR}
    AND resource_id = #{resourceId,jdbcType=BIGINT}
    AND result <> 'SUCCESS'
